export function mergeCalendars(a: Event[], b: Event[]): Event[] {
  const all = [...a, ...b].sort((x, y) => x.start - y.start)
  const out: Event[] = []
  for (const e of all) {
    const last = out[out.length - 1]
    if (last && last.end === e.start) {
      last.end = e.end
    } else {
      out.push({ ...e })
    }
  }
  return out
}

